WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ex_d_material'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '物资分配最值', 'kp-ex-d-material', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "数列构造最值"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "求某项最大，就让其他项尽可能小；求某项最小，就让其他项尽可能大。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“5 个人的总分是 400 分，每个人分数不同，排第 3 的人最多得多少分？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出 5 个坑位: 1 2 3 4 5] --> B[设目标位置(如第3名)为 x]\nB --> C[根据'求第三名最大', 让其他人尽可能小]\nC --> D[第4名设为x-1, 第5名设为x-2]\nD --> E[第1名和第2名的分数不能限制, 但也要尽可能小, 因为要给第三名留出空间]\nE --> F[所以第2名为x+1, 第1名为x+2 (前提是没有给出他们的分数上限)]\nF --> G[全部加起来 = 总分, 求解 x]"}}]}$$ AS jsonb), NULL, '物资分配最值的核心考点与实战推导。', category_node.id, CAST('["数量关系", "物资分配最值"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ex_d_material", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
